import React from "react";
import { useNavigate } from "react-router-dom";
import { AiFillStar } from "react-icons/ai";
import { FiMapPin } from "react-icons/fi";
import { FaRegHeart } from "react-icons/fa";
import errorImage from '../../images/errorLoading.png';

interface SalonCardProps {
  id: string;
  image: string;
  name: string;
  distance: string;
  location: string;
  rating: number;
  reviews: number;
  onClick: () => void;  // Add this line
}

const SalonCard: React.FC<SalonCardProps> = ({
  id,
  image,
  name,
  distance,
  location,
  rating,
  reviews,
  onClick   // Add this line
}) => {
  const navigate = useNavigate();
  const [imgSrc, setImgSrc] = React.useState(image || errorImage);

  return (
    <div
      onClick={onClick}  // Replace navigate with onClick
      style={{
        width: "280px",
        height: "211px",
        backgroundColor: "#fff",
        borderRadius: "10px",
        boxShadow: "0 4px 10px rgba(0,0,0,0.12)",
        cursor: "pointer",
        overflow: "hidden",
      }}
    >
      {/* Image */}
      <div style={{ position: "relative" }}>
        <img
          src={imgSrc}
          alt={name}
          onError={() => setImgSrc(errorImage)}
          style={{
            width: "100%",
            height: "120px",
            objectFit: "cover",
          }}
        />

        {/* Heart icon */}
        <div
          style={{
            position: "absolute",
            top: "8px",
            right: "8px",
            background: "rgba(255,255,255,0.85)",
            borderRadius: "50%",
            padding: "6px",
          }}
        >
          <FaRegHeart color="#76949F" size={16 as number} />
        </div>
      </div>

      {/* Text */}
      <div style={{ padding: "8px 12px" }}>
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            fontWeight: 600,
            fontSize: "15px",
          }}
        >
          <span>{name}</span>
          <span style={{ color: "#7A7A7A", fontSize: "13px" }}>{distance}</span>
        </div>

        <div
          style={{
            display: "flex",
            alignItems: "center",
            marginTop: "3px",
            color: "#7A7A7A",
            fontSize: "13px",
          }}
        >
          <FiMapPin size={14 as number} style={{ marginRight: "4px" }} />
          {location}
        </div>

        <div
          style={{
            display: "flex",
            alignItems: "center",
            marginTop: "4px",
            fontSize: "13px",
            fontWeight: 500,
          }}
        >
          <AiFillStar
            color="#FFD03F"
            size={16 as number}
            style={{ marginRight: "4px" }}
          />
          <span>{rating}</span>
          <span style={{ color: "#7A7A7A", marginLeft: "4px" }}>
            ({reviews})
          </span>
        </div>
      </div>
    </div>
  );
};

export default SalonCard;
